    assertTrue(preciseEqualStr(exchange, result1, std::string("percentage"), std::string("20.0")));
    assertTrue(preciseEqualStr(exchange, result1, std::string("average"), std::string("5.5")));
    assertTrue(preciseEqualStr(exchange, result1, std::string("close"), std::string("6.0")));
    assertTrue(preciseEqualStr(exchange, result1, std::string("last"), std::string("6.0")));
    // CASE 2 - by open
    std::any ticker2 = ccxt::dict {
        { std::string("open"), 5 },
        { std::string("percentage"), 20 },
    };
