    assertTrue(preciseEqualStr(exchange, result2, std::string("average"), std::string("5.5")));
    assertTrue(preciseEqualStr(exchange, result2, std::string("close"), std::string("6.0")));
    assertTrue(preciseEqualStr(exchange, result2, std::string("last"), std::string("6.0")));
    // CASE 3 - by close
    std::any ticker3 = ccxt::dict {
        { std::string("close"), 6 },
        { std::string("change"), 1 },
    };
    std::any result3 = exchange.safeTicker(ticker3);
