    assertTrue(preciseEqualStr(exchange, result5, std::string("change"), std::string("1.0")));
    assertTrue(preciseEqualStr(exchange, result5, std::string("close"), std::string("6.0")));
    assertTrue(preciseEqualStr(exchange, result5, std::string("last"), std::string("6.0")));
    // CASE 6
